package dev.exodus.teleporter.client;
import dev.exodus.teleporter.menu.ExodusTeleporterMenu;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;
public final class ExodusTeleporterScreen extends AbstractContainerScreen<ExodusTeleporterMenu>{private static final ResourceLocation TEXTURE=new ResourceLocation("minecraft","textures/gui/container/dispenser.png");public ExodusTeleporterScreen(ExodusTeleporterMenu menu,Inventory inv,Component title){super(menu,inv,title);imageHeight=166;imageWidth=306;inventoryLabelY=72;}private net.minecraft.client.gui.components.Button claimButton,spawnButton;
 @Override protected void init(){super.init();claimButton=addRenderableWidget(net.minecraft.client.gui.components.Button.builder(Component.literal("Claim Device"),b->{minecraft.gameMode.handleInventoryButtonClick(menu.containerId,0);}).bounds(leftPos+181,topPos+24,120,20).build());spawnButton=addRenderableWidget(net.minecraft.client.gui.components.Button.builder(Component.literal("Set Spawnpoint"),b->{minecraft.gameMode.handleInventoryButtonClick(menu.containerId,1);}).bounds(leftPos+181,topPos+50,120,20).build());}
 @Override protected void containerTick(){super.containerTick();claimButton.active=menu.canClaim();spawnButton.active=menu.canSetSpawn();}
 @Override protected void renderBg(GuiGraphics g,float partial,int mx,int my){g.blit(TEXTURE,leftPos,topPos,0,0,176,imageHeight);g.fill(leftPos+176,topPos,leftPos+306,topPos+166,0xED20202B);for(int i=0;i<9;i++)if(menu.getSlot(i).getItem().isEmpty()){int x=leftPos+62+(i%3)*18,y=topPos+17+(i/3)*18;g.renderFakeItem(new net.minecraft.world.item.ItemStack(dev.exodus.teleporter.ExodusTeleporterRegistry.item(dev.exodus.teleporter.domain.TeleporterComponent.forSlot(i)).get()),x,y);g.fill(x,y,x+16,y+16,0x99000000);}}@Override protected void renderLabels(GuiGraphics g,int mx,int my){super.renderLabels(g,mx,my);g.drawString(font,menu.installedCount()+"/9 Components Installed",8,62,0x404040,false);}@Override public void render(GuiGraphics g,int mx,int my,float partial){renderBackground(g);super.render(g,mx,my,partial);renderTooltip(g,mx,my);}}
